135	    /// Connects manually by default. Automatic attempts respect a preceding explicit Disconnect.
136	    @discardableResult
137	    public func connect(to address: RobotAddress, automatically: Bool = false) async -> Bool {
138	        guard !automatically || automaticConnectionAllowed else { return false }
139	        if !automatically {
140	            automaticConnectionAllowed = true
141	        }
142	
143	        let attemptID = UUID()
144	        connectionAttemptID = attemptID
145	        resetConnectionState()
146	        self.address = address
147	        phase = .connecting(.handshaking)
148	        lastError = nil
149	
150	        do {
151	            let client = try makeClient(address)
152	            let handshake = try await client.handshake()
153	            guard connectionAttemptID == attemptID, !Task.isCancelled else {
154	                if connectionAttemptID == attemptID {
155	                    resetConnectionState()
156	                }
157	                return false
158	            }
159	            // Claimed before the readiness stage so `startBackend()` has something
160	            // to talk to while the attempt sits on `.backendUnavailable`. Only the
161	            // stepper is mounted then, so the rest of the surface stays unreachable.
162	            self.client = client
163	            lastStatus = handshake.status
164	            compatibilityWarning = handshake.compatibility.warningMessage
165	            KnownRobots.lastAddress = address
166	            phase = .connecting(.checkingBackend(handshake.identity))
167	            return await settleReadiness(
168	                identity: handshake.identity,
169	                status: handshake.status,
170	                client: client,
171	                attemptID: attemptID,
172	                automatically: automatically
173	            )
174	        } catch {
175	            guard connectionAttemptID == attemptID else { return false }
176	            guard !Task.isCancelled else {
177	                resetConnectionState()
178	                return false
179	            }
180	            return failAttempt(.connect, error: error, address: address, automatically: automatically)
181	        }
182	    }
