277	    /// Polls the daemon's authoritative running-task list so natural completion
278	    /// clears the UI. Two misses avoid racing task registration just after play.
279	    private func startMonitoring(_ playback: MovePlayback, client: any RobotAPIClient) {
280	        movePollTask?.cancel()
281	        movePollTask = Task { [configuration] in
282	            var consecutiveMisses = 0
283	            while !Task.isCancelled, currentMove?.uuid == playback.uuid {
284	                try? await Task.sleep(for: configuration.movePollInterval)
285	                guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
286	                do {
287	                    let running = try await client.runningMoveUUIDs()
288	                    guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
289	                    if running.contains(playback.uuid) {
290	                        consecutiveMisses = 0
291	                    } else {
292	                        consecutiveMisses += 1
293	                        if consecutiveMisses >= 2 {
294	                            try? await client.stopSound()
295	                            guard !Task.isCancelled, currentMove?.uuid == playback.uuid else { return }
296	                            currentMove = nil
297	                            movePollTask = nil
298	                            return
299	                        }
300	                    }
301	                } catch {
302	                    // A transient status failure must not claim that playback ended.
303	                }
304	            }
305	        }
306	    }
