308	    /// Network changes shouldn't wait for the next poll tick: losing the path
309	    /// drops to `.unreachable` immediately; regaining it restarts polling now.
310	    func startPathMonitor(identity: RobotIdentity) {
311	        pathMonitor?.cancel()
312	        let monitor = NWPathMonitor()
313	        monitor.pathUpdateHandler = { [weak self] path in
314	            let satisfied = path.status == .satisfied
315	            Task { @MainActor in
316	                self?.pathChanged(satisfied: satisfied, identity: identity)
317	            }
318	        }
319	        monitor.start(queue: .main)
320	        pathMonitor = monitor
321	    }
