323	    private func pathChanged(satisfied: Bool, identity: RobotIdentity) {
324	        guard client != nil else { return }
325	        if !satisfied {
326	            if case .connected = phase {
327	                phase = .unreachable(identity)
328	            }
329	        } else if case .unreachable = phase {
330	            startPolling(identity: identity)
331	        }
332	    }
