338	            while !Task.isCancelled {
339	                try? await Task.sleep(for: configuration.pollInterval)
340	                guard !Task.isCancelled, let client = self.client else { return }
341	                do {
342	                    let status = try await client.daemonStatus()
343	                    lastStatus = status
344	                    if case .unreachable = phase {
